// Original assertions without an external test framework; nonzero exit on any failure.
using Greyhaven.Content;
using Greyhaven.Server;
using Server;
var root=Path.GetFullPath(args[0]);using var package=new ContentPackage(root,Path.Combine(root,"content/original/maps/reach-fixture.json"));var world=new OriginalWorld(package);int count=0;
void Test(string name,Action body){body();count++;Console.WriteLine("PASS "+name);}
void Assert(bool ok,string message="Assertion failed"){if(!ok)throw new Exception(message);}
void Fails(Action body){try{body();}catch(ContentException){return;}throw new Exception("Expected explicit content error.");}
Test("content roots accept a trailing directory separator",()=>{using var p=new ContentPackage(root+Path.DirectorySeparatorChar,Path.Combine(root,"content/original/maps/reach-fixture.json"));Assert(p.MapHash==package.MapHash);});
Test("published Phase 5 map hash remains loadable",()=>Assert(package.AcceptsMapHash("54d5dfb36ba60630997d5207966a81552ae87862e82b2a70b2ae48f526b6e8ff")));
Test("content catalogs and all runtime assets verify",()=>{package.VerifyAll();Assert(package.Definitions.Terrain.Count==4&&package.Definitions.Statics.Count==19&&package.Definitions.Items.Count==13&&package.Audio.Count==39);});
Test("ServUO land/static blocks agree with original map",()=>world.VerifyEngineView());
Test("ServUO numeric adapters preserve names, height, collision and wet flags",()=>{foreach(var d in package.Definitions.Terrain){Assert(TileData.LandTable[d.NumericId].Name==package.Localize(d.NameKey));Assert(TileData.LandTable[d.NumericId].Flags.HasFlag(TileFlag.Impassable)==d.Impassable);}foreach(var d in package.Definitions.Statics)Assert(TileData.ItemTable[d.NumericId].Height==d.Height);});
Test("CentrED native tile-data adapter agrees with shared catalog",()=>CentrED.OriginalTileDataAdapter.Verify(package));
Test("legacy server lookup fails before probing a legacy path",()=>{Assert(Core.DataDirectories.Count==0);try{Core.FindDataFile("tiledata.mul");}catch(InvalidOperationException){return;}throw new Exception("Legacy lookup was not blocked.");});
Test("shore and placed wall/tree collision block standing",()=>{Assert(!package.CanStand(package.Map,0,0));Assert(!package.CanStand(package.Map,10,16));Assert(!package.CanStand(package.Map,18,13));Assert(package.CanStand(package.Map,16,19));});
Test("invalid and zero movement vectors fail safely",()=>{foreach(var v in new[]{int.MinValue,-2,2,int.MaxValue})Assert(!package.CanStep(package.Map,16,19,v,0));Assert(!package.CanStep(package.Map,16,19,0,0));});
Test("diagonal corner clipping is rejected",()=>{var m=package.Map.Clone();m.Get(17,19).Terrain="greyhaven.terrain.water";Assert(!package.CanStep(m,16,19,1,1));});
Test("height changes over two units are blocked",()=>{var m=package.Map.Clone();m.Get(17,19).Z=3;Assert(!package.CanStep(m,16,19,1,0));m.Get(17,19).Z=2;Assert(package.CanStep(m,16,19,1,0));});
Test("map validation rejects invalid cells and blocked spawn",()=>{var m=package.Map.Clone();m.Get(0,0).Terrain="unknown";Fails(()=>package.ValidateMap(m));m=package.Map.Clone();m.Get(m.Spawn.X,m.Spawn.Y).Terrain="greyhaven.terrain.water";Fails(()=>package.ValidateMap(m));});
Test("map validation rejects duplicate placement identities",()=>{var m=package.Map.Clone();m.Statics.Add(m.Statics[0]);Fails(()=>package.ValidateMap(m));});
Test("map export preserves original source and reloads elevation/statics",()=>{var m=package.Map.Clone();var original=package.MapHash;m.Get(15,19).Terrain="greyhaven.terrain.stone";m.Get(15,19).Z=2;m.Statics.Add(new(){Id="test.lantern",Definition="greyhaven.static.lantern",X=15,Y=19,Z=2});string p=Path.Combine(Path.GetTempPath(),"greyhaven-map-"+Guid.NewGuid()+".json");try{package.SaveMap(m,p);using var loaded=new ContentPackage(root,p);Assert(loaded.Map.Get(15,19).Z==2&&loaded.Map.Statics.Count==10);Assert(package.MapHash==original);Assert(loaded.MapHash!=original);}finally{File.Delete(p);}});
Test("server transfer rejects nonwearable item",()=>{var item=world.State.Items.First(i=>i.Definition.EndsWith("healing-tonic"));Assert(!world.Handle(new(){Type="transfer",ItemId=item.Id,Destination="equipped"}).Ok);Assert(item.Where=="bag");});
Test("server hat replacement returns previous equipment to backpack",()=>{var wizard=world.State.Items.First(i=>i.Definition.EndsWith("wizard-hat"));var trail=world.State.Items.First(i=>i.Definition.EndsWith("trail-hat"));Assert(world.Handle(new(){Type="transfer",ItemId=wizard.Id,Destination="equipped"}).Ok);Assert(world.State.Items.First(i=>i.Id==wizard.Id).Where=="equipped"&&world.State.Items.First(i=>i.Id==trail.Id).Where=="bag");});
Test("server ground and backpack transfers retain a single item identity",()=>{var item=world.State.Items.First(i=>i.Definition.EndsWith("healing-tonic"));Assert(world.Handle(new(){Type="transfer",ItemId=item.Id,Destination="ground",X=16,Y=20}).Ok);Assert(world.State.Items.First(i=>i.Id==item.Id).Where=="ground");Assert(world.Handle(new(){Type="transfer",ItemId=item.Id,Destination="bag",X=80,Y=140}).Ok);Assert(world.State.Items.First(i=>i.Id==item.Id).Where=="bag"&&world.State.Items.Count(i=>i.Id==item.Id)==1);});
Test("server rejects out-of-range drops and unknown identities",()=>{var item=world.State.Items.First(i=>i.Definition.EndsWith("healing-tonic"));Assert(!world.Handle(new(){Type="transfer",ItemId=item.Id,Destination="ground",X=24,Y=20}).Ok);Assert(!world.Handle(new(){Type="transfer",ItemId="unknown",Destination="bag"}).Ok);});
Test("server commits integer tile movement and prevents immediate double steps",()=>{var a=world.Handle(new(){Type="step",Dx=1,Dy=0});Assert(a.Ok&&world.State.X==17&&world.State.Y==19);Assert(!world.Handle(new(){Type="step",Dx=1,Dy=0}).Ok);});
Test("provider rejects paths outside root and unknown text",()=>{Fails(()=>package.ReadBytes("../tiledata.mul","test"));Fails(()=>package.ReadBytes("tiledata.mul","test"));Fails(()=>package.ReadBytes("/tmp/outside.png","test"));Fails(()=>package.Localize("legacy.unknown"));});
Test("all audited runtime files are original package assets",()=>Assert(package.Accesses.All(a=>!new[]{".mul",".uop",".idx",".def",".ttf",".ico"}.Contains(Path.GetExtension(a.Path).ToLowerInvariant()))));
string campaignRoot=Path.Combine(Path.GetTempPath(),"greyhaven-campaign-"+Guid.NewGuid());
try {
 var store=new CampaignStore(campaignRoot,"slot1");
 Test("campaign IDs cannot traverse directories",()=>Fails(()=>new CampaignStore(campaignRoot,"../bad")));
 Test("save roundtrip preserves full authoritative state and map",()=>{world.State.ElapsedSeconds=123.5;store.Write(package,world.State,"manual");var saved=store.Read("manual");CampaignStore.Validate(package,saved);Assert(saved.State.X==world.State.X&&saved.State.ElapsedSeconds==123.5&&saved.State.Items.Count==10&&saved.Map.Cells.Count==1024);});
 Test("a second host cannot write the same campaign",()=>{using var held=store.AcquireHostLock();Fails(()=>store.AcquireHostLock());});
 Test("atomic save retains previous verified backup",()=>{world.State.ElapsedSeconds=321;store.Write(package,world.State,"manual");Assert(store.Read("manual").State.ElapsedSeconds==321);File.WriteAllText(Path.Combine(campaignRoot,"UserData/Campaigns/slot1/manual.json"),"damaged");Assert(store.Read("manual").State.ElapsedSeconds==123.5&&store.RecoveryNotice!=null);});
 Test("both damaged copies fail without resetting campaign",()=>{File.WriteAllText(Path.Combine(campaignRoot,"UserData/Campaigns/slot1/manual.json.bak"),"damaged");Fails(()=>store.Read("manual"));Assert(store.Exists);});
 Test("restore rejects duplicate item identities and incompatible packages",()=>{store.Write(package,world.State,"quick");var saved=store.Read("quick");saved.State.Items.Add(saved.State.Items[0]);Fails(()=>world.Restore(saved));saved=store.Read("quick");saved.Fingerprint="incompatible";Fails(()=>world.Restore(saved));});
 Test("restore rejects bad positions, equipment and elapsed time",()=>{foreach(var change in new Action<CampaignSave>[]{s=>s.State.X=-1,s=>s.State.ElapsedSeconds=double.NaN,s=>s.State.Items[0].Where="unknown",s=>s.State.Items.First(i=>i.Where=="bag").X=999}){var saved=store.Read("quick");change(saved);Fails(()=>world.Restore(saved));}});
 Test("restored campaign pauses and rejects movement and transfers",()=>{world.Restore(store.Read("quick"));Assert(world.State.Paused);Assert(!world.Handle(new(){Type="step",Dx=1}).Ok);Assert(!world.Handle(new(){Type="transfer",ItemId=world.State.Items[0].Id,Destination="bag"}).Ok);});
 Test("incomplete saved map or state fails explicitly",()=>{var saved=store.Read("quick");saved.Map.Cells=null!;Fails(()=>CampaignStore.Validate(package,saved));saved=store.Read("quick");saved.State.Items=null!;Fails(()=>CampaignStore.Validate(package,saved));});
 Test("checksum protects otherwise valid JSON payloads",()=>{store.Write(package,world.State,"autosave");var path=Path.Combine(campaignRoot,"UserData/Campaigns/slot1/autosave.json");var envelope=System.Text.Json.JsonSerializer.Deserialize<SaveEnvelope>(File.ReadAllText(path),ContentPackage.Json)!;envelope.Payload+=" ";File.WriteAllText(path,Wire.Encode(envelope));Fails(()=>store.Read("autosave"));});
 Test("save kinds cannot traverse directories",()=>Fails(()=>store.Write(package,world.State,"../../bad")));
}finally{if(Directory.Exists(campaignRoot))Directory.Delete(campaignRoot,true);}
Console.WriteLine(count+" content, authority and campaign tests passed.");
